const e=$json.execution||{};
const w=$json.workflow||{};
const err=e.error||{};
const safeMessage=String(err.message||'Unknown workflow error').slice(0,1200);
const report=[
`Workflow failure alert`,
`Workflow: ${w.name||'Unknown'}`,
`Execution ID: ${e.id||'Unavailable'}`,
`Execution URL: ${e.url||'Unavailable'}`,
`Error: ${safeMessage}`,
`Time: ${new Date().toISOString()}`,
'',
'Review the failed execution in n8n. Avoid forwarding candidate resume text or other personal data in alert emails.'
].join('\\n');
return [{json:{report}}];
